#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Guided data entry, first cut (issue #23): a Vocabulary tab inside the
# spreadsheet, and dropdowns on STONE Name and PRODUCT type that read from it.
# Every stage is something you do in Google Sheets; this script never touches
# the sheet itself. Run it from anywhere:  bash tools/sheet-vocabulary-wizard.sh

TOTAL_STAGES=9

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
STONE_TABLE="$REPO/data/stone-names.json"
VOCAB_TAB="Vocabulary"

# The library remembers answers in ENV_FILE. Point it at a scratch file so a
# re-run picks up where you stopped, and the app's own .env is never written.
ENV_FILE="${TMPDIR:-/tmp}/ezoko-vocabulary-wizard.state"

# What the app is already configured for, offered as the default. Only these
# two non-secret keys are read.
APP_ENV="${EZOKO_STATE_DIR:-$HOME/Library/Application Support/Ezoko}/.env"
app_setting() {
  [[ -f "$APP_ENV" ]] || return 0
  local line
  line=$(grep -E "^${1}=" "$APP_ENV" | tail -n1) || return 0
  line="${line#*=}"; line="${line%\"}"; line="${line#\"}"
  printf '%s' "$line"
}

# copy_clip "text" puts text on the clipboard, or prints it when it can't.
copy_clip() {
  local text="$1"
  if   command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$text" | LC_ALL=en_US.UTF-8 pbcopy
  elif command -v wl-copy  >/dev/null 2>&1; then printf '%s' "$text" | wl-copy
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$text" | xclip -selection clipboard
  elif command -v clip.exe >/dev/null 2>&1; then printf '%s' "$text" | clip.exe
  else
    warn "no clipboard tool found; copy this by hand:"
    printf '%s\n' "$text"
    return 0
  fi
  printf '  %s✓ copied to your clipboard%s\n' "$GREEN" "$RESET"
}

# show "text" prints something the human will paste, set apart from the prose.
show() { printf '\n      %s%s%s\n\n' "$BOLD" "$1" "$RESET"; }

# ask_column KEY "Prompt" is ask, repeated until the answer is a column letter.
ask_column() {
  local key="$1" value
  while true; do
    ask "$key" "$2"
    value=$(printf '%s' "${!key}" | tr '[:lower:]' '[:upper:]' | tr -d '[:space:]')
    if [[ "$value" =~ ^[A-Z]{1,2}$ ]]; then printf -v "$key" '%s' "$value"; return; fi
    warn "that should be a column letter such as C or AB"
  done
}

# Every spelling the app recognises plus every English name it produces,
# straight from data/stone-names.json, so the list is as current as the repo.
stone_list() {
  node - "$STONE_TABLE" <<'JS'
const table = require(process.argv[2]);
const titleCase = (raw) =>
  raw.trim().replace(/\s+/g, ' ').toLocaleLowerCase('hu-HU')
    .replace(/(^|[\s\-/])(\p{L})/gu, (_, p, l) => p + l.toLocaleUpperCase('hu-HU'));
const entries = Object.entries(table).filter(([key]) => !key.startsWith('_'));
const seen = new Map();
for (const [, english] of entries) seen.set(english.toLowerCase(), english);
for (const [hungarian] of entries) {
  const key = hungarian.trim().toLowerCase();
  if (!seen.has(key)) seen.set(key, titleCase(hungarian));
}
console.log([...seen.values()].sort((a, b) => a.localeCompare(b, 'hu')).join('\n'));
JS
}

# data/ keeps no type list (a new type needs no code change), so these are the
# eight seen in the sheet so far. The audit stage shows any the sheet has beyond them.
TYPE_LIST=$'CARVING\nSPHERE\nCRYSTAL\nTUMBLE STONE\nSMALL FIGURES\nTOWER\nHEART\nPENDANT'

command -v node >/dev/null 2>&1 || { echo "Node is needed to build the stone list. Install it, or run this from the machine you develop on."; exit 1; }
[[ -f "$STONE_TABLE" ]] || { echo "Cannot find $STONE_TABLE. Keep this script in the repo's tools/ folder."; exit 1; }
STONE_LIST="$(stone_list)"
STONE_COUNT=$(printf '%s\n' "$STONE_LIST" | wc -l | tr -d ' ')

banner "Ezoko sheet: Vocabulary tab and two dropdowns"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Open the sheet"
say "Everything happens in the spreadsheet the data-entry person fills in."
note "Nothing in this wizard changes a cell that already has a value, and every"
note "rule it adds can be removed again from Data > Data validation."
printf '\n'
APP_SHEET_ID="$(app_setting GOOGLE_SHEET_ID)"
if [[ -z "$(_existing SHEET_URL || true)" && -n "$APP_SHEET_ID" ]]; then
  note "The app on this machine reads: https://docs.google.com/spreadsheets/d/$APP_SHEET_ID/edit"
  note "Press Enter to use that one, or paste another sheet's URL."
fi
ask SHEET_URL "Sheet URL:"
[[ -z "$SHEET_URL" && -n "$APP_SHEET_ID" ]] && SHEET_URL="https://docs.google.com/spreadsheets/d/$APP_SHEET_ID/edit"
[[ -n "$SHEET_URL" ]] || { warn "no sheet URL given; run the wizard again when you have it"; exit 1; }
write_env SHEET_URL "$SHEET_URL"
open_url "$SHEET_URL"
step "Check you are signed in as someone who can edit it."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Find the product tab and the two columns"
say "Look at the tab that holds the product rows, and at its header row."
printf '\n'
APP_TAB="$(app_setting GOOGLE_SHEET_TAB)"
if [[ -z "$(_existing DATA_TAB || true)" && -n "$APP_TAB" ]]; then
  note "The app reads the tab named \"$APP_TAB\". Press Enter if that is the one."
fi
ask DATA_TAB "Name of the product tab, exactly as written at the bottom:"
[[ -z "$DATA_TAB" && -n "$APP_TAB" ]] && DATA_TAB="$APP_TAB"
[[ -n "$DATA_TAB" ]] || { warn "no tab name given; run the wizard again"; exit 1; }
write_env DATA_TAB "$DATA_TAB"
printf '\n'
step "Find the header that starts with STONE Name."
ask_column STONE_COL "Its column letter:"
write_env STONE_COL "$STONE_COL"
step "Find the header that starts with PRODUCT type."
warn "not PRODUCT name: that one stays free text"
ask_column TYPE_COL "Its column letter:"
write_env TYPE_COL "$TYPE_COL"

# Sheets wants a tab name in single quotes, with any apostrophe doubled.
DATA_REF="'${DATA_TAB//\'/\'\'}'"
STONE_RANGE="$DATA_REF!${STONE_COL}2:${STONE_COL}"
TYPE_RANGE="$DATA_REF!${TYPE_COL}2:${TYPE_COL}"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the Vocabulary tab"
say "The dropdowns read their values from a tab of their own, so adding a"
say "stone later means adding a row there, not editing a rule."
printf '\n'
step "Click the + at the bottom left to add a tab."
step "Double-click its name and rename it to exactly:"
show "$VOCAB_TAB"
step "Type these four headers into row 1:"
show "A1  Stones          B1  Types"
show "D1  Stones in the sheet, not in the list"
show "E1  Types in the sheet, not in the list"
warn "keep \"$DATA_TAB\" as the leftmost tab; leave $VOCAB_TAB to its right"
note "When no tab name is saved on the setup page, the app reads the leftmost tab."
note "With $VOCAB_TAB to the right, the new tab changes nothing for it."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Paste the stones"
say "$STONE_COUNT names: every spelling the app recognises, Hungarian and English,"
say "built just now from data/stone-names.json."
printf '\n'
copy_clip "$STONE_LIST"
step "In the $VOCAB_TAB tab, click cell A2 and paste."
step "The list should end at row $((STONE_COUNT + 1)), with Yooperlite last."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Paste the types"
say "The eight product types seen in the sheet so far, in capitals as the sheet"
say "writes them."
printf '\n'
copy_clip "$TYPE_LIST"
step "Click cell B2 and paste."
step "The list should end at row 9, with PENDANT last."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Audit what the sheet already contains"
say "Before switching anything on, see which values already typed into the"
say "sheet are missing from the two lists."
printf '\n'
STONE_AUDIT="=IFERROR(SORT(UNIQUE(FILTER(TRIM($STONE_RANGE); TRIM($STONE_RANGE)<>\"\"; COUNTIF(A2:A; TRIM($STONE_RANGE))=0))); \"nothing missing\")"
TYPE_AUDIT="=IFERROR(SORT(UNIQUE(FILTER(TRIM($TYPE_RANGE); TRIM($TYPE_RANGE)<>\"\"; COUNTIF(B2:B; TRIM($TYPE_RANGE))=0))); \"nothing missing\")"
copy_clip "$STONE_AUDIT"
step "Click cell D2 in the $VOCAB_TAB tab, paste, press Enter."
pause "Press Enter for the second formula"
copy_clip "$TYPE_AUDIT"
step "Click cell E2, paste, press Enter."
printf '\n'
note "If Sheets reports a formula error, replace every ; with , and try again."
printf '\n'
say "Columns D and E now list everything the dropdowns would flag. For each:"
step "A real stone or type: add it to the bottom of column A or B. It then"
say "  disappears from D or E by itself."
step "A typo: fix it in the product tab."
step "A lone ? is the placeholder for \"not decided\". Leave it; it will be"
say "  flagged, which is harmless."
note "An unfamiliar stone added to column A works in the dropdown at once, but the"
note "app does not know it until data/stone-names.json gains it too. Until then the"
note "product is still created, with a warning in the run report."
note "Keep columns D and E. They stay live and show new off-list values later."
pause "Press Enter when D and E show only what you are content to leave flagged"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Dropdown on STONE Name"
say "Go back to the \"$DATA_TAB\" tab."
printf '\n'
step "Menu: Data > Data validation. A panel opens on the right."
step "Click Add rule."
step "Apply to range: clear the box and paste this (it is on your clipboard):"
show "$STONE_RANGE"
copy_clip "$STONE_RANGE"
pause "Press Enter once it is pasted, for the next value"
step "Criteria: choose Dropdown (from a range), then paste into the box beside it:"
show "$VOCAB_TAB!A2:A"
copy_clip "$VOCAB_TAB!A2:A"
step "Open Advanced options."
step "If the data is invalid: choose Show a warning."
note "Reject the input would stop a brand new stone being typed at all, and there"
note "is no way yet for the data-entry person to add one to the list."
step "Display style: Arrow keeps cells looking as they do now. Chip adds colour."
step "Click Done."
note "The labels are Google's and shift now and then. If one is missing, stop and"
note "say which, rather than choosing the nearest thing."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Dropdown on PRODUCT type"
say "The same again for the type column. The panel should still be open;"
say "otherwise Data > Data validation."
printf '\n'
step "Click Add rule."
step "Apply to range: clear the box and paste:"
show "$TYPE_RANGE"
copy_clip "$TYPE_RANGE"
pause "Press Enter once it is pasted, for the next value"
step "Criteria: Dropdown (from a range), then paste:"
show "$VOCAB_TAB!B2:B"
copy_clip "$VOCAB_TAB!B2:B"
step "Advanced options > If the data is invalid: Show a warning."
step "Display style: the same as you chose for stones."
step "Click Done. The panel should now list two rules."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Check it behaves"
say "Use an empty row at the bottom of \"$DATA_TAB\"."
printf '\n'
step "Click the STONE Name cell and type ame. The list should narrow to"
say "  Amethyst and Ametiszt. Pick one with Enter."
step "In the same cell type xyz and press Enter. The value should stay, with"
say "  a red corner on the cell. That is Show a warning doing its job."
step "Type agate in lower case. Note whether Sheets flags it: the app treats"
say "  agate and Agate alike, so a flag here is cosmetic."
step "Try the PRODUCT type cell the same way with sph."
step "Scroll up: existing rows must read exactly as before. Any red corners are"
say "  the values columns D and E already listed."
step "Clear the test row."
printf '\n'
if confirm "Did all of that behave as described?"; then
  CHECKED=yes
else
  CHECKED=no
fi

finish
if [[ "$CHECKED" == yes ]]; then
  say "The $VOCAB_TAB tab and both dropdowns are in place."
  say "Run a Preview in the app: it should report the same rows as before."
else
  warn "Something did not match. To undo: Data > Data validation, then Remove"
  warn "rule on each. Cell values are untouched either way. Note what differed."
fi
note "Not part of this cut: letting the data-entry person add a new value from"
note "the cell, required fields per type, and keeping the Vocabulary tab in step"
note "with data/stone-names.json. Until that last one exists, re-run stage 4's"
note "paste after the stone table changes."
note "Answers were remembered in $ENV_FILE; delete it when you are done."
printf '\n'
